     2| * IVX Senior Developer — one-click, no-token, in-process production self-proof.
     3| *
     4| * WHY THIS EXISTS
     5| *   The Senior Developer mutation route (`POST /api/ivx/senior-developer/run`)
     6| *   is intentionally gated by a real Supabase owner bearer. That makes a live,
     7| *   end-to-end proof (create feature -> commit to GitHub -> deploy to Render ->
     8| *   verify live) impossible to trigger without first minting an owner JWT, and
     9| *   the GitHub/Render/Supabase credentials only exist on the PRODUCTION runtime
    10| *   (never in a developer sandbox).
    11| *
    12| *   This module removes that friction for the OWNER: it runs the exact same real
    13| *   runtime IN-PROCESS in `systemMode` (so it uses the production-side
    14| *   credentials directly), then persists a compact, secret-free proof to durable
    15| *   Supabase storage so it survives the very deploy it triggers.
    16| *
    17| * LOOP / ABUSE SAFETY
    18| *   - A hard cooldown (`SELF_PROOF_COOLDOWN_MS`) means a fresh commit+deploy can
    19| *     be triggered at most once per window; within the window the durable cached
    20| *     proof is returned instead of pushing another commit.
    21| *   - An in-process lock prevents concurrent runs.
    22| *   - The underlying runtime only ever writes allowlisted, non-destructive
    23| *     generated-feature files — never secrets, never destructive edits.
    24| */
    25|import { mkdir, readFile, writeFile } from 'node:fs/promises';
    26|import path from 'node:path';
    27|import { auditDir } from './ivx-data-root';
    28|import { isDurableStoreConfigured, readDurableJson, writeDurableJson } from './ivx-durable-store';
    29|import {
    30|  IVX_GIT_DEPLOY_CONFIRM_TEXT,
    31|  IVX_SAFE_PATCH_CONFIRM_TEXT,
    32|  runIVXSeniorDeveloperTask,
    33|} from './ivx-senior-developer-runtime';
    34|
    35|export const IVX_SENIOR_DEVELOPER_SELF_PROOF_MARKER = 'ivx-senior-developer-self-proof-v1';
    36|
    37|/** Minimum gap between real commit+deploy runs. Within this window the cached proof is served. */
    38|const SELF_PROOF_COOLDOWN_MS = 10 * 60 * 1000;
    39|
    40|const ROOT = auditDir('senior-developer-self-proof');
    41|const STATE_FILE = path.join(ROOT, 'latest.json');
    42|
    43|/** Compact, secret-free, owner-readable proof of the full end-to-end run. */
    44|export type IVXSeniorDeveloperSelfProof = {
    45|  marker: typeof IVX_SENIOR_DEVELOPER_SELF_PROOF_MARKER;
    46|  ok: boolean;
    47|  endToEndProductionComplete: boolean;
    48|  goal: string;
    49|  jobId: string;
    50|  /** 1. New feature created */
    51|  feature: {
    52|    built: boolean;
    53|    slug: string | null;
    54|    title: string | null;
    55|    liveRoute: string | null;
    56|    liveUrl: string | null;
    57|  };
    58|  /** 2. Commit pushed + 3. GitHub SHA */
    59|  github: {
    60|    committed: boolean;
    61|    commitSha: string | null;
    62|    commitUrl: string | null;
    63|    branch: string | null;
    64|    committedPaths: string[];
    65|    /** Raw GitHub API failure (status + message + docs url), secret-free, when the commit fails. */
    66|    error: string | null;
    67|  };
    68|  /** 4. Render deployment triggered */
    69|  render: {
    70|    deployTriggered: boolean;
    71|    deployId: string | null;
    72|    deployStatus: string | null;
    73|    /** Raw Render API failure, secret-free, when the deploy trigger fails. */
    74|    error: string | null;
    75|  };
    76|  /** 5. Production HTTP 200 from the live feature subsystem */
    77|  production: {
