   116|async function readLatest(): Promise<IVXSeniorDeveloperSelfProof | null> {
   117|  try {
   118|    if (isDurableStoreConfigured()) {
   119|      const value = await readDurableJson<IVXSeniorDeveloperSelfProof | null>(STATE_FILE, null);
   120|      return value && value.marker === IVX_SENIOR_DEVELOPER_SELF_PROOF_MARKER ? value : null;
   121|    }
   122|    const raw = await readFile(STATE_FILE, 'utf8');
   123|    const parsed = JSON.parse(raw) as IVXSeniorDeveloperSelfProof;
   124|    return parsed && parsed.marker === IVX_SENIOR_DEVELOPER_SELF_PROOF_MARKER ? parsed : null;
   125|  } catch {
   126|    return null;
   127|  }
   128|}
   129|
   130|async function persistLatest(proof: IVXSeniorDeveloperSelfProof): Promise<void> {
   131|  try {
   132|    if (isDurableStoreConfigured()) {
   133|      await writeDurableJson(STATE_FILE, proof);
   134|      return;
   135|    }
   136|    await mkdir(ROOT, { recursive: true });
   137|    await writeFile(STATE_FILE, `${JSON.stringify(proof, null, 2)}\n`, 'utf8');
   138|  } catch (error) {
   139|    console.log('[IVXSeniorDeveloperSelfProof] persist failed:', error instanceof Error ? error.message : 'unknown');
   140|  }
