   157|    goal,
   158|    systemMode: true,
   159|    approvePatch: true,
   160|    patchConfirmationText: IVX_SAFE_PATCH_CONFIRM_TEXT,
   161|    approveGitDeploy: true,
   162|    gitDeployConfirmationText: IVX_GIT_DEPLOY_CONFIRM_TEXT,
   163|    validationMode: 'focused',
   164|  });
