   167|  const generatedFeature = (r.generatedFeature ?? {}) as Record<string, unknown>;
   168|  const gitDeployOperator = (r.gitDeployOperator ?? {}) as Record<string, unknown>;
   169|  const github = ((gitDeployOperator.github ?? {}) as Record<string, unknown>);
   170|  const render = ((gitDeployOperator.render ?? {}) as Record<string, unknown>);
   171|  const productionVerification = ((r.productionVerification ?? {}) as Record<string, unknown>);
   172|  const changedRouteVerification = ((r.changedRouteVerification ?? {}) as Record<string, unknown>);
   173|  const validations = Array.isArray(r.validations) ? r.validations : [];
   174|  const changedFiles = Array.isArray(r.changedFiles) ? r.changedFiles : [];
   175|  const feature = (generatedFeature.feature ?? null) as Record<string, unknown> | null;
   176|
   177|  const asString = (value: unknown): string | null => (typeof value === 'string' && value.length > 0 ? value : null);
   178|  const asNumber = (value: unknown): number | null => (typeof value === 'number' && Number.isFinite(value) ? value : null);
   179|  const asStringArray = (value: unknown): string[] => (Array.isArray(value) ? value.filter((entry): entry is string => typeof entry === 'string') : []);
   180|
   181|  const liveRoute = asString(generatedFeature.liveRoute);
   182|  const commitSha = asString(github.commitSha);
   183|  const committed = gitDeployOperator.status === 'executed' && Boolean(commitSha);
   184|  const validationPassed = validations.length > 0 && validations.every((entry) => Boolean((entry as { ok?: boolean }).ok));
   185|  const ok = Boolean(r.ok);
   186|
   187|  return {
   188|    marker: IVX_SENIOR_DEVELOPER_SELF_PROOF_MARKER,
   189|    ok,
   190|    endToEndProductionComplete: Boolean(r.endToEndProductionComplete),
   191|    goal: asString(r.goal) ?? goal,
   192|    jobId: asString(r.jobId) ?? '',
